/* Curated examples are produced ahead of time, never generated by this page. */
(function (host) {
  'use strict';
  function create({ root, document, fetch, confirm }) {
    let manifestPromise, revision = 0, renderedDay = null, fetchedAt = 0;
    const safeImage = value => /^\/assets\/showcase\/day[1-4]-[1-3]\.(jpg|webp)$/.test(value);
    function manifest() {
      if (!manifestPromise || Date.now()-fetchedAt>15000) { fetchedAt=Date.now(); manifestPromise = fetch('/assets/showcase/manifest.json', { cache: 'no-store' })
        .then(response => { if (!response.ok) throw new Error('Gallery unavailable'); return response.json(); })
        .catch(() => null); }
      return manifestPromise;
    }
    async function render(module, { promptField, onUse }) {
      const current = ++revision;
      if (!root) return;
      if (!/^day_[1-4]$/.test(module.id) || !['available', 'completed'].includes(module.state)) {
        root.hidden = true; renderedDay = null; return;
      }
      const data = await manifest();
      if (current !== revision) return;
      if (!data || data.published !== true || !Array.isArray(data.entries)) { root.hidden = true; renderedDay=null; return; }
      const day = Number(module.id.slice(4));
      const examples = data.entries.filter(item => item.day === day);
      if (examples.length !== 3 || examples.some(item => item.status !== 'approved' || !safeImage(item.image) || typeof item.prompt !== 'string')) {
        root.hidden = true; return;
      }
      root.hidden = false;
      const renderKey=day+':'+examples.map(item=>item.sha256||item.image).join(',');
      if (renderedDay === renderKey) return;
      renderedDay = renderKey;
      const heading = document.createElement('h3'); heading.textContent = 'Today’s Inspiration';
      const label = document.createElement('p'); label.className = 'muted small';
      label.textContent = 'AI-generated course examples. Compare the choices, then make your own. These are curated examples, not student work or guaranteed results.';
      const grid = document.createElement('div'); grid.className = 'showcase-grid';
      for (const example of examples) {
        const card = document.createElement('article'); card.className = 'showcase-card';
        const image = document.createElement('img'); image.src = example.image; image.alt = example.alt || example.title;
        image.width = 800; image.height = 600; image.loading = 'lazy'; image.decoding = 'async';
        const fallback = document.createElement('p'); fallback.className = 'showcase-image-fallback'; fallback.hidden = true;
        fallback.textContent = 'Example image temporarily unavailable. You can still explore its prompt.';
        image.addEventListener('error', () => { image.hidden = true; fallback.hidden = false; });
        const title = document.createElement('h4'); title.textContent = example.title;
        const teaching = document.createElement('p'); teaching.className = 'small'; teaching.textContent = example.explanation;
        const details = document.createElement('details'); const summary = document.createElement('summary'); summary.textContent = 'Read the exact prompt';
        const prompt = document.createElement('p'); prompt.textContent = example.prompt; details.append(summary, prompt);
        const references = document.createElement('p'); references.className = 'muted small';
        references.textContent = example.references?.length ? 'Reference-based example: attach the preceding example image in Gemini before using this prompt.' : 'Text-only example: no reference image required.';
        const download = document.createElement('a'); download.href = example.image; download.download = example.id + '.' + example.image.split('.').pop(); download.className = 'showcase-download'; download.textContent = 'Download example';
        const button = document.createElement('button'); button.type = 'button'; button.className = 'secondary'; button.textContent = 'Use this prompt';
        button.addEventListener('click', () => {
          const existing = promptField.value.trim();
          if (existing && existing !== example.prompt && !confirm('Replace the prompt currently in your Prompt Lab? Your submitted work will not change.')) return;
          promptField.value = example.prompt;
          onUse(example);
          promptField.focus();
          promptField.scrollIntoView?.({ behavior: 'smooth', block: 'center' });
        });
        card.append(image, fallback, title, teaching, details, references, download, button); grid.append(card);
      }
      root.replaceChildren(heading, label, grid);
    }
    return { render };
  }
  if (typeof module !== 'undefined' && module.exports) module.exports = { create };
  else host.MeuseShowcase = { create };
})(typeof window !== 'undefined' ? window : globalThis);
